    prev_lag : INT := 0;
    prev_count : INT := 0;
    tmp_demand : INT;
    tmp_min_hours : LINT;
    tmp_min_pump : INT;
    tmp_lag_pump : INT;
    tmp_i : INT;
END_VAR
```

